@props([
    'is' => 'div',
    'variant' => 'default',
    'size' => 'default',
])

@php
    use Knppy\Ui\Facades\Ui;

    $classes = Ui::classes()
        ->add('group/item flex flex-wrap items-center rounded-md border border-transparent text-sm transition-colors duration-100 outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 [a]:transition-colors [a]:hover:bg-accent/50')
        ->add(match ($variant) {
            'outline' => 'border-border',
            'muted' => 'bg-muted/50',
            default => 'bg-transparent',
        })
        ->add($size === 'sm' ? 'gap-2.5 px-4 py-3' : 'gap-4 p-4')
        ->add($attributes['class'] ?? '');
@endphp

<{{ $is }}
    data-slot="item"
    data-variant="{{ $variant }}"
    data-size="{{ $size }}"
    {{ $attributes->twMerge(['class' => $classes]) }}
    >{{ $slot }}</{{ $is }}
>

@props(['variant' => 'default'])

@php
    use Knppy\Ui\Facades\Ui;

    $classes = Ui::classes()
        ->add('flex shrink-0 items-center justify-center gap-2 group-has-[[data-slot=item-description]]/item:translate-y-0.5 group-has-[[data-slot=item-description]]/item:self-start [&_svg]:pointer-events-none')
        ->add(match ($variant) {
            'icon' => "size-8 rounded-sm border bg-muted [&_svg:not([class*='size-'])]:size-4",
            'image' => 'size-10 overflow-hidden rounded-sm [&_img]:size-full [&_img]:object-cover',
            default => 'bg-transparent',
        })
        ->add($attributes['class'] ?? '');
@endphp

<div data-slot="item-media" data-variant="{{ $variant }}" {{ $attributes->twMerge(['class' => $classes]) }}>
    {{ $slot }}
</div>
